target.css:
:root {
  --ink: #17212b;
  --muted: #667482;
  --paper: #ffffff;
  --panel: #f2f6f7;
  --line: #d7e0e4;
  --navy: #233849;
  --cyan: #18a9bd;
  --cyan-soft: #dff5f7;
  --lime: #7cba3e;
  --lime-soft: #edf6df;
  --amber: #e69c32;
  --amber-soft: #fff1d9;
  --red: #d95555;
}

* {
  box-sizing: border-box;
}

.uplink {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 62px;
  padding: 12px 16px;
  background: var(--navy);
  color: var(--paper);
}

.identity {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid var(--cyan);
  border-radius: 9px;
  color: var(--cyan);
  font-size: 20px;
  line-height: 1;
}

.titles p,
.section-head p {
  margin: 0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.eyebrow {
  color: var(--cyan);
}

.titles h1 {
  margin: 2px 0 0;
  font-size: 19px;
  line-height: 1;
  letter-spacing: -0.3px;
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border: 1px solid var(--lime);
  border-radius: 999px;
  color: var(--lime);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.status b {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lime);
}

.console {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 12px 16px;
}

.orbit,
.telemetry {
  min-width: 0;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.orbit {
  background: var(--panel);
}

.section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted);
}

.section-head span {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.4px;
}

.beacon {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 54px;
  margin: 7px 0 8px;
  overflow: hidden;
  border-radius: 9px;
  background: var(--navy);
  color: var(--paper);
}

.beacon::before,
.beacon::after {
  position: absolute;
  border: 1px solid var(--cyan);
  border-radius: 50%;
  content: "";
}

.beacon::before {
  width: 74px;
  height: 74px;
  opacity: 0.5;
}

.beacon::after {
  width: 42px;
  height: 42px;
}

.beacon i {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
}

.beacon strong {
  z-index: 1;
  font-size: 22px;
  line-height: 1;
}

.beacon small {
  position: absolute;
  right: 9px;
  bottom: 7px;
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.bands {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.band {
  display: grid;
  grid-template-columns: 7px 1fr auto;
  align-items: center;
  gap: 6px;
  font-size: 10px;
}

.band em {
  width: 7px;
  height: 7px;
  border-radius: 2px;
}

.band span {
  color: var(--muted);
  font-weight: 700;
}

.band strong {
  font-size: 10px;
}

.cyan em { background: var(--cyan); }
.lime em { background: var(--lime); }
.amber em { background: var(--amber); }

.packet {
  padding: 3px 5px;
  border-radius: 4px;
  background: var(--cyan-soft);
  color: var(--cyan);
}

.readings {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  margin-top: 9px;
}

.reading {
  padding: 9px 5px 8px;
  text-align: center;
  border-radius: 8px;
  background: var(--panel);
}

.reading > span {
  display: block;
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.4px;
}

.reading strong {
  display: block;
  margin-top: 4px;
  color: var(--navy);
  font-size: 16px;
  line-height: 1;
}

.reading strong span {
  font-size: 9px;
}

.route {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.route span {
  color: var(--lime);
  font-size: 11px;
}

.route strong {
  margin-left: auto;
  color: var(--lime);
  font-size: 8px;
  letter-spacing: 0.5px;
}

.footnote {
  display: flex;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

